def nid(i,j,k):
    kk=key(i,j,k)
    if kk not in nodes:
        nodes[kk]=len(coords)+1; coords.append(node_xyz(i,j,k))
    return nodes[kk]

hexes=[]; quads={'neck_flank':[],'lid_flank':[],'inner_end':[],'outer_end':[]}
for i in range(NTH):
    for j in range(NS):
